/*
 * Counts only. No email addresses leave D1: this report is about which posts
 * convert, and the list itself stays where it is.
 */
const totalsRes = $('Count subscribers').first().json;
const pagesRes = $('Which pages converted').first().json;

const firstRows = (res) => res?.result?.[0]?.results ?? [];
const totals = firstRows(totalsRes)[0] ?? {};
const pages = firstRows(pagesRes);

if (totalsRes?.success === false) {
  return [{ json: { failed: true, message: JSON.stringify(totalsRes.errors ?? totalsRes).slice(0, 500) } }];
}

const lines = [
  `Total subscribers: ${totals.total ?? 0}`,
  `Confirmed: ${totals.confirmed ?? 0}`,
  `New in the last 7 days: ${totals.last_7_days ?? 0}`,
  '',
  'Where they signed up:',
  ...(pages.length
    ? pages.map((p) => `  ${p.n.toString().padStart(3)}  ${p.source_path || '(unknown)'}`)
    : ['  nobody signed up this week']),
  '',
  'Sending is still off: addresses are collected in D1 and will be mailed from a',
  'newsletter tool once the list is worth emailing.',
];

return [{ json: { failed: false, report: lines.join('\n'), total: totals.total ?? 0 } }];
